import { readFileSync } from 'node:fs';

/** Exact generated bytes from ed9fbbc0d's canonical atlas directory. This is
 * source evidence, NOT an owner approval: the real pack says runtimeReady=false.
 * Positive tests change that single admission field on a private parsed copy. */
export const harvesterManifestBytes = readFileSync(new URL('./testFixtures/pe_harvesters.manifest.json', import.meta.url));
export interface RawHarvesterClip {
  [key: string]: unknown;
  frames: Array<{ key: string; sourceIndex: number; rgbaSha256: string }>;
}
export interface RawHarvesterManifest {
  [key: string]: unknown;
  runtimeReady: boolean;
  atlases: string[];
  clips: Record<string, RawHarvesterClip>;
  bindings: Record<string, { sha256: string; value: Record<string, unknown> }>;
}
export function harvesterFixture(admitted = false): RawHarvesterManifest {
  const value = JSON.parse(harvesterManifestBytes.toString('utf8')) as RawHarvesterManifest;
  if (admitted) value.runtimeReady = true;
  return value;
}
